import json
import sqlite3
from typing import List, Dict, Any, Optional, Tuple

# --- Optional dependencies ---
# pip install pymilvus sentence-transformers

# =====================
# Fixed configuration (as required)
# =====================
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

MILVUS = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

NEO4J = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def connect_sqlite(db_path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def safe_json_loads(val: Any) -> Any:
    if val is None:
        return None
    if isinstance(val, (dict, list)):
        return val
    if isinstance(val, (bytes, bytearray)):
        try:
            val = val.decode('utf-8', errors='ignore')
        except Exception:
            return None
    if isinstance(val, str):
        val = val.strip()
        if not val:
            return None
        try:
            return json.loads(val)
        except Exception:
            # sometimes attributes are stored as python-ish strings; keep raw
            return val
    return val


def pick_attr(attributes: Any, key: str) -> Optional[Any]:
    attrs = safe_json_loads(attributes)
    if isinstance(attrs, dict):
        return attrs.get(key)
    return None


def text_contains(hay: Optional[str], needles: List[str]) -> bool:
    if not hay:
        return False
    h = hay.lower()
    return any(n.lower() in h for n in needles)


def load_candidate_businesses(
    city: str,
    state: str,
    min_stars: float = 4.0,
    min_reviews: int = 100,
    limit: int = 800,
    cuisine_keywords: Optional[List[str]] = None
) -> List[Dict[str, Any]]:
    cuisine_keywords = cuisine_keywords or []

    conn = connect_sqlite(sqlite_paths["business"])
    try:
        # Note: Yelp categories is a comma-separated string.
        sql = (
            "SELECT business_id, name, address, city, state, postal_code, latitude, longitude, "
            "stars, review_count, categories, attributes, is_open "
            "FROM business "
            "WHERE is_open=1 "
            "  AND categories LIKE '%Restaurants%' "
            "  AND city = ? AND state = ? "
            "  AND stars >= ? AND review_count >= ? "
            "LIMIT ?"
        )
        rows = conn.execute(sql, (city, state, min_stars, min_reviews, limit)).fetchall()
        businesses = [dict(r) for r in rows]

        # Optional cuisine filtering in python (more flexible)
        if cuisine_keywords:
            filtered = []
            for b in businesses:
                cats = b.get('categories', '') or ''
                if text_contains(cats, cuisine_keywords):
                    filtered.append(b)
            businesses = filtered

        return businesses
    finally:
        conn.close()


def build_date_night_query_text(cuisine: str, extra: str) -> str:
    base = (
        "fancy upscale romantic date night restaurant. great ambiance, intimate, candlelit, "
        "dressy, cocktails, wine list, reservations, special occasion, anniversary"
    )
    parts = [base]
    if cuisine and cuisine.strip():
        parts.append(f"Cuisine preference: {cuisine.strip()}")
    if extra and extra.strip():
        parts.append(f"Extra preferences: {extra.strip()}")
    return " | ".join(parts)


def try_get_embedder():
    try:
        from sentence_transformers import SentenceTransformer
        return SentenceTransformer('all-MiniLM-L6-v2')
    except Exception as e:
        return None


def try_connect_milvus():
    try:
        from pymilvus import connections
        connections.connect(alias='default', host=MILVUS['milvus_host'], port=MILVUS['milvus_port'])
        return True
    except Exception:
        return False


def milvus_collection_handle(name: str):
    from pymilvus import Collection
    return Collection(name)


def infer_milvus_fields(col) -> Tuple[str, Optional[str], List[str]]:
    """Infer (vector_field, business_id_field, output_text_fields) from collection schema.
    This makes the script more robust to schema differences.
    """
    vector_field = None
    business_field = None
    text_fields = []

    for f in col.schema.fields:
        # Vector field
        if str(getattr(f, 'dtype', '')).lower().find('float_vector') >= 0:
            vector_field = f.name
        # Common scalar fields
        lname = f.name.lower()
        if lname in ('business_id', 'businessid'):
            business_field = f.name
        if lname in ('text', 'content', 'review_text', 'tip_text'):
            text_fields.append(f.name)

    if vector_field is None:
        # fallback guess
        vector_field = 'embedding'
    return vector_field, business_field, text_fields


def milvus_semantic_search(
    query_text: str,
    candidate_business_ids: List[str],
    topk: int = 60
) -> List[Dict[str, Any]]:
    """Return hits: [{source, business_id, score, text?}]"""
    embedder = try_get_embedder()
    if embedder is None:
        raise RuntimeError('sentence-transformers not available; install sentence-transformers to use vector search.')

    query_vec = embedder.encode([query_text], normalize_embeddings=True).tolist()

    from pymilvus import utility

    hits_all: List[Dict[str, Any]] = []

    # Keep expr length reasonable
    # Milvus expr for string IDs: business_id in ["...", "..."]
    def chunks(lst, n):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    for src_key, col_name in [('reviews', MILVUS['milvus_collections']['reviews']), ('tips', MILVUS['milvus_collections']['tips'])]:
        if not utility.has_collection(col_name):
            continue

        col = milvus_collection_handle(col_name)
        col.load()

        vector_field, business_field, text_fields = infer_milvus_fields(col)
        if business_field is None:
            # If we can't filter by business, we can still search globally but results may be noisy
            business_field = 'business_id'

        out_fields = [business_field]
        if text_fields:
            out_fields.extend(text_fields[:1])

        search_params = {'metric_type': 'IP', 'params': {'nprobe': 10}}

        # Search per chunk to keep expr manageable
        for bid_chunk in chunks(candidate_business_ids, 500):
            # quote string ids
            quoted = ','.join([f'"{x}"' for x in bid_chunk])
            expr = f"{business_field} in [{quoted}]"

            res = col.search(
                data=query_vec,
                anns_field=vector_field,
                param=search_params,
                limit=min(topk, 60),
                expr=expr,
                output_fields=out_fields
            )
            # res is list (nq) of hits
            for hit in res[0]:
                ent = hit.entity
                bid = ent.get(business_field, None)
                txt = None
                if text_fields:
                    txt = ent.get(text_fields[0], None)
                hits_all.append({
                    'source': src_key,
                    'business_id': bid,
                    'score': float(hit.score),
                    'text': txt
                })

    # Higher IP score = more similar (since normalized).
    hits_all.sort(key=lambda x: x['score'], reverse=True)
    return hits_all[:topk]


def fallback_keyword_snippets(candidate_business_ids: List[str], keywords: List[str], limit: int = 80) -> List[Dict[str, Any]]:
    """If Milvus isn't available, do a lightweight keyword match on SQLite reviews/tips.
    Returns pseudo-hits with heuristic score.
    """
    kw_like = ' OR '.join(["text LIKE ?" for _ in keywords])
    params = [f"%{k}%" for k in keywords]

    hits: List[Dict[str, Any]] = []

    def chunks(lst, n):
        for i in range(0, len(lst), n):
            yield lst[i:i+n]

    # Reviews
    conn_r = connect_sqlite(sqlite_paths['review'])
    try:
        for bid_chunk in chunks(candidate_business_ids, 900):
            placeholders = ','.join(['?'] * len(bid_chunk))
            sql = f"SELECT business_id, text FROM review WHERE business_id IN ({placeholders}) AND ({kw_like}) LIMIT {limit}"
            rows = conn_r.execute(sql, (*bid_chunk, *params)).fetchall()
            for r in rows:
                t = r['text'] or ''
                score = sum(1 for k in keywords if k.lower() in t.lower())
                hits.append({'source': 'reviews_sql', 'business_id': r['business_id'], 'score': float(score), 'text': t[:240]})
    finally:
        conn_r.close()

    # Tips
    conn_t = connect_sqlite(sqlite_paths['tip'])
    try:
        for bid_chunk in chunks(candidate_business_ids, 900):
            placeholders = ','.join(['?'] * len(bid_chunk))
            sql = f"SELECT business_id, text FROM tip WHERE business_id IN ({placeholders}) AND ({kw_like}) LIMIT {limit}"
            rows = conn_t.execute(sql, (*bid_chunk, *params)).fetchall()
            for r in rows:
                t = r['text'] or ''
                score = sum(1 for k in keywords if k.lower() in t.lower())
                hits.append({'source': 'tips_sql', 'business_id': r['business_id'], 'score': float(score), 'text': t[:240]})
    finally:
        conn_t.close()

    hits.sort(key=lambda x: x['score'], reverse=True)
    return hits[:limit]


def business_quality_score(b: Dict[str, Any]) -> float:
    # simple normalized quality: stars (0-5) + review_count log
    stars = float(b.get('stars') or 0.0)
    rc = float(b.get('review_count') or 0.0)
    import math
    return 0.75 * (stars / 5.0) + 0.25 * (math.log1p(rc) / math.log1p(5000))


def date_night_bonus(b: Dict[str, Any]) -> float:
    """Heuristic bonuses from business attributes if available.
    Yelp attributes often include keys like: RestaurantsReservations, DressCode, Ambience, RestaurantsPriceRange2
    Values are sometimes strings 'True'/'False' or nested dict strings.
    """
    attrs = safe_json_loads(b.get('attributes'))
    bonus = 0.0

    def truthy(v) -> bool:
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return v != 0
        if isinstance(v, str):
            return v.strip().lower() in ('true', '1', 'yes')
        return False

    if isinstance(attrs, dict):
        if truthy(attrs.get('RestaurantsReservations')):
            bonus += 0.05
        dress = attrs.get('DressCode')
        if isinstance(dress, str) and dress.strip().lower() in ('dressy', 'formal'):  # date-night leaning
            bonus += 0.05
        # Ambience can be dict or stringified dict
        amb = safe_json_loads(attrs.get('Ambience'))
        if isinstance(amb, dict):
            if truthy(amb.get('romantic')):
                bonus += 0.08
            if truthy(amb.get('intimate')):
                bonus += 0.06
        price = attrs.get('RestaurantsPriceRange2')
        try:
            p = int(price)
            if p >= 3:  # 3-4 usually pricier
                bonus += 0.05
        except Exception:
            pass

    return bonus


def recommend_date_night_restaurants(
    city: str,
    state: str,
    cuisine: str = '',
    extra_prefs: str = '',
    topn: int = 10
) -> List[Dict[str, Any]]:
    candidates = load_candidate_businesses(
        city=city,
        state=state,
        min_stars=4.0,
        min_reviews=100,
        limit=800,
        cuisine_keywords=[c.strip() for c in cuisine.split(',') if c.strip()] if cuisine else None
    )
    if not candidates:
        return []

    bid_to_business = {b['business_id']: b for b in candidates}
    candidate_ids = list(bid_to_business.keys())

    query_text = build_date_night_query_text(cuisine=cuisine, extra=extra_prefs)

    # Try Milvus semantic search; fallback to keyword search
    semantic_hits: List[Dict[str, Any]] = []
    milvus_ok = try_connect_milvus()
    if milvus_ok:
        try:
            semantic_hits = milvus_semantic_search(query_text, candidate_ids, topk=80)
        except Exception as e:
            semantic_hits = []

    if not semantic_hits:
        keywords = [
            'romantic', 'date night', 'anniversary', 'intimate', 'upscale', 'fancy',
            'reservation', 'cocktail', 'wine', 'ambience', 'tasting menu', 'chef'
        ]
        semantic_hits = fallback_keyword_snippets(candidate_ids, keywords, limit=80)

    # Aggregate best semantic score per business
    best_hit: Dict[str, Dict[str, Any]] = {}
    for h in semantic_hits:
        bid = h.get('business_id')
        if not bid or bid not in bid_to_business:
            continue
        if bid not in best_hit or h['score'] > best_hit[bid]['score']:
            best_hit[bid] = h

    # Score fusion
    scored: List[Tuple[float, str]] = []
    for bid, b in bid_to_business.items():
        q = business_quality_score(b)
        bonus = date_night_bonus(b)
        s = best_hit.get(bid, {}).get('score', 0.0)

        # Normalize semantic score roughly:
        # - If Milvus IP similarity: usually 0~1
        # - If keyword fallback: small integer
        if s > 1.5:  # likely keyword fallback
            sem = min(s / 8.0, 1.0)
        else:
            sem = max(min(s, 1.0), 0.0)

        final = 0.55 * q + 0.40 * sem + 0.05 * bonus
        scored.append((final, bid))

    scored.sort(reverse=True, key=lambda x: x[0])

    results: List[Dict[str, Any]] = []
    for final, bid in scored[:topn]:
        b = bid_to_business[bid]
        hit = best_hit.get(bid)
        # compact display
        results.append({
            'business_id': bid,
            'name': b.get('name'),
            'stars': b.get('stars'),
            'review_count': b.get('review_count'),
            'address': f"{b.get('address','')}, {b.get('city','')}, {b.get('state','')} {b.get('postal_code','')}".strip(),
            'categories': b.get('categories'),
            'attributes': b.get('attributes'),
            'why': {
                'final_score': round(final, 4),
                'best_match_source': hit.get('source') if hit else None,
                'best_match_score': round(hit.get('score'), 4) if hit else None,
                'snippet': (hit.get('text')[:260] if hit and hit.get('text') else None)
            }
        })

    return results


if __name__ == '__main__':
    # ---- Interactive inputs (so it works even if user didn't specify details) ----
    print('Date-night fancy restaurant recommender (Yelp dataset)')
    city = input('City (e.g., Las Vegas): ').strip() or 'Las Vegas'
    state = input('State (e.g., NV): ').strip() or 'NV'
    cuisine = input('Cuisine keywords (optional, comma-separated; e.g., Italian, Steakhouse): ').strip()
    extra = input('Extra preferences (optional; e.g., rooftop, live jazz, tasting menu, quiet): ').strip()

    try:
        recs = recommend_date_night_restaurants(city=city, state=state, cuisine=cuisine, extra_prefs=extra, topn=10)
        if not recs:
            print('No candidates found. Try lowering constraints (different city/state, or fewer cuisine keywords).')
        else:
            print('
Top recommendations:
')
            for i, r in enumerate(recs, 1):
                print(f"{i}. {r['name']}  |  {r['stars']}★ ({r['review_count']} reviews)")
                print(f"   {r['address']}")
                if r.get('categories'):
                    print(f"   Categories: {r['categories']}")
                why = r.get('why', {})
                if why.get('snippet'):
                    print(f"   Why: {why.get('best_match_source')} match (score={why.get('best_match_score')}): {why.get('snippet')}")
                print(f"   Final score: {why.get('final_score')}")
                print('')
    except Exception as e:
        print('Failed to generate recommendations:', repr(e))
        print('Tips: ensure SQLite DB files exist; to enable semantic search, start Milvus and install pymilvus + sentence-transformers.')

